from pathlib import Path

root = Path(__file__).parent
names = ['千禧年打工桌面', '赛博打工日报', '人类进程终端', '出租屋物语']
descs = ['Win98 窗口、密集行情，最接近原作的荒诞日常。', '暖纸与朱红，把每一天的暴击写成一张小报。', '黑琥珀终端，让自己成为系统里最后的人类进程。', '手绘小屋与对话选择，先让你在乎这个普通人。']
cards = []
for i, letter in enumerate('abcd'):
    fragment = (root / 'parts' / f'{letter}.html').read_text()
    cards.append(f'<article class="direction" data-direction="{letter.upper()}"><div class="direction-label"><strong>{letter.upper()} · {names[i]}</strong><span>{"推荐" if i == 0 else "方向样机"}</span></div><div class="stage" inert>{fragment}</div><div class="choice"><button class="qmdp-pick-button" data-qmdp-managed="page" data-id="{letter.upper()}" data-name="{names[i]}">选择 {letter.upper()} · {names[i]}</button></div></article>')

page = '''<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>AI 浮生记 · 四个设计方向</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f3f1;color:#20211f;font:14px/1.6 system-ui,-apple-system,"PingFang SC",sans-serif}header{border-bottom:1px solid #d7d8d3;background:#fafaf8;padding:20px max(20px,calc((100vw - 1240px)/2));display:flex;justify-content:space-between;gap:20px;align-items:center}header h1{font-size:19px;margin:0}header p{font-size:12px;color:#686a64;margin:4px 0 0}.shortcuts{font-size:12px;color:#686a64;white-space:nowrap}main{max-width:1280px;margin:auto;padding:22px 20px 50px}.dials{display:grid;grid-template-columns:repeat(3,1fr);gap:25px;margin-bottom:22px}.dials label{font-size:12px;color:#55574f}.dials b{font-size:13px;color:#20211f;display:flex;justify-content:space-between;margin-bottom:8px}.dials input{width:100%;accent-color:#323b32}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.direction{background:white;border:1px solid #d6d7d0;border-radius:8px;overflow:hidden}.direction-label{padding:12px 16px;display:flex;justify-content:space-between;gap:10px;font-size:13px}.direction-label span{font-size:11px;color:#647060}.stage{height:370px;overflow:hidden}.choice{padding:12px 16px}.qmdp-pick-button{width:100%;background:#283329;color:white;border:0;padding:12px;border-radius:5px;font:600 13px system-ui;cursor:pointer}.qmdp-pick-button:hover{background:#414f42}button:focus-visible{outline:2px solid #727e68;outline-offset:3px}.selected{outline:2px solid #65735d;outline-offset:2px}.explanations{margin:24px 0 0;display:grid;grid-template-columns:repeat(2,1fr);gap:10px 30px;font-size:12px;color:#61645b}.explanations p{margin:0}.explanations b{color:#272e24}.explanations small{grid-column:1/-1;font-size:12px;margin-top:9px}dialog{max-width:450px;width:calc(100% - 32px);border:1px solid #d6d7d0;border-radius:10px;padding:25px;color:#20211f}dialog::backdrop{background:#0008}dialog h2{font-size:20px;margin:0 0 10px}dialog p{color:#62655c;font-size:13px}textarea{width:100%;height:88px;margin:10px 0 16px;border:1px solid #b8bdb0;border-radius:5px;padding:10px;font:14px system-ui;resize:vertical}.dialog-actions{display:flex;gap:10px}.dialog-actions button{flex:1;padding:12px;border:0;border-radius:5px;font:600 13px system-ui;cursor:pointer}.dialog-actions button:last-child{background:#283329;color:#fff}#response{font-size:12px;margin:14px 0 0;color:#5a624f}.error{color:#af251b!important}@media(max-width:760px){header{align-items:start}.shortcuts{display:none}.grid{grid-template-columns:1fr}.dials{gap:12px}.dials label{font-size:10px}.dials b{font-size:12px}.explanations{grid-template-columns:1fr}main{padding:18px 12px}.direction-label{padding:12px}.choice{padding:12px}header{padding:18px}.dials input{min-height:28px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
</style></head><body><header><div><h1>AI 浮生记 · 选一个时代的表情</h1><p>四个设计方向样机，选定后实现完整游戏。</p></div><span class="shortcuts">键盘 1 — 4 选择 · Esc 返回</span></header><main><div class="dials" data-qmdp-dials>'''
for key, title, n, explain in [('variance', '视觉冒险度', 7, '熟悉 ← → 大胆'), ('motion', '动效强度', 3, '安静 ← → 活泼'), ('density', '信息密度', 7, '舒展 ← → 紧凑')]:
    page += f'<label><b>{title}<output id="{key}Out" data-qmdp-output="{key}">{n}</output></b><input id="{key}" data-qmdp-dial="{key}" type="range" min="1" max="10" value="{n}" aria-label="{title}">{explain}</label>'
page += '</div><div class="grid">' + ''.join(cards) + '</div><div class="explanations">'
for i, desc in enumerate(descs):
    page += f'<p><b>{"ABCD"[i]} · {names[i]}</b> — {desc}</p>'
page += '''<small>推荐 A：保留《北京浮生记》的电脑小游戏记忆，和 AI 时代的荒诞形成反差。也可以在确认时提出混搭建议。</small></div></main><dialog id="confirm"><h2 id="confirmTitle">确认设计方向</h2><p id="meta"></p><label for="adjustments">想调整的地方（可选）</label><textarea id="adjustments" placeholder="比如：要 A 的窗口，配 B 的文字气质"></textarea><div class="dialog-actions"><button id="cancel">取消</button><button id="submit">确认并回传</button></div><p id="response" role="status" aria-live="polite"></p></dialog><script>
let pending=null;const dialog=document.querySelector('dialog');const dialValues=()=>Object.fromEntries(['variance','motion','density'].map(k=>[k,+document.getElementById(k).value]));document.querySelectorAll('.dials input').forEach(el=>el.addEventListener('input',()=>document.getElementById(el.id+'Out').textContent=el.value));
function choose(button){pending={id:button.dataset.id,name:button.dataset.name,label:'选 '+button.dataset.id+'：'+button.dataset.name};const d=dialValues();document.getElementById('meta').textContent=pending.label+' · 视觉冒险度 '+d.variance+' / 动效强度 '+d.motion+' / 信息密度 '+d.density;document.getElementById('response').textContent='';dialog.showModal();}
document.querySelectorAll('.qmdp-pick-button').forEach(b=>b.addEventListener('click',()=>choose(b)));document.getElementById('cancel').onclick=()=>dialog.close();document.addEventListener('keydown',e=>{if(dialog.open||/INPUT|TEXTAREA/.test(e.target.tagName))return;const i='1234'.indexOf(e.key);if(i>=0)choose(document.querySelectorAll('.qmdp-pick-button')[i]);});
document.getElementById('submit').onclick=async()=>{const button=document.getElementById('submit');button.disabled=true;const payload={...pending,dials:dialValues(),adjustments:document.getElementById('adjustments').value.trim()};const status=document.getElementById('response');try{const res=await fetch('/api/select',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await res.json();if(!res.ok||!result.ok)throw Error('回传未成功');document.querySelectorAll('.direction').forEach(el=>el.classList.toggle('selected',el.dataset.direction===payload.id));status.className='';status.textContent='已选择 '+payload.id+'，已回传。';button.textContent='已回传';}catch(error){status.className='error';status.textContent='回传失败，请重试或在对话中发送“'+payload.label+'”。';button.disabled=false;}};
</script></body></html>'''
(root / 'index.html').write_text(page)
